export default function FarmingIncentives(props: FarmingIncentivesProps) {
  const { setIsOpenPre, setIsOpenFarmingModal, setFarmingModalAction, apiVaultInfo } = props

  const [isOpen, setIsOpen] = useState(false)
  const { vaultsFarmsRewardObj } = useVaultsListV2Store()

  const currentVaultsFarmsReward = useMemo(() => {
    return vaultsFarmsRewardObj[apiVaultInfo?.vaultId]
  }, [vaultsFarmsRewardObj, apiVaultInfo?.vaultId])

  const { vaultsFarmingObj } = useVaultsFarmingStore()
  const isVaultsFarming = useMemo(() => {
    return currentVaultsFarmsReward?.[apiVaultInfo?.vaultId]?.isVaultsFarming
  }, [vaultsFarmingObj, apiVaultInfo?.vaultId])

  const {
    vaultFarmingApr,
    vaultFarmingAprDisplay,
    vaultFarmingLoading,
    farmingTvl,
    farmingTvlDisplay,
    stakeVaultFarmingTvl,
    stakeVaultFarmingTvlLoading,
    vaultFarmingRewardAmountUSD,
    vaultFarmingRewardLoading,
    holdingAmountDisplay,
    holdCoinAValue,
    holdCoinBValue,
    farmClaimAction,
    farmClaimLoading,
    vaultsFarmingStakeLoading,
    vaultsFarmingStaked,
    currentVaultPositionLoading,
    currentVaultPositionInfo,
    vaultsFarmingAvailableRewards,
    vaultsFarmingAvailableRewardsLoading,
    stakeButtonDisabled,
    claimButtonDisabled,
    unStakeButtonDisabled
  } = useVaultFarmingOverview(apiVaultInfo, currentVaultsFarmsReward, true)

  return (
    <VStack border="1px solid" borderColor="border" gap="12px" w="100%" borderRadius="8px">
      <HStack
        w="100%"
        p="16px 12px"
        borderRadius="7px"
        bg="primary_opacity.10"
        justifyContent="space-between"
        onClick={() => setIsOpen(!isOpen)}
        cursor="pointer"
      >
        <HStack gap="4px" cursor="pointer" userSelect="none">
          <Text color="text_caption" userSelect="none">
            Farm Overview
          </Text>
          <TooltipIcon tooltipCon="Powered by Haedal" />
        </HStack>
        {/* <Text color="text_highlight">APR {vaultFarmingAprDisplay}</Text> */}
        <Icon fontSize="12px" xlinkHref="#icon-icon_arrow" transition="transform 0.5s" transform={isOpen ? 'rotate(180deg)' : 'rotate(0deg)'} />
      </HStack>
      {isOpen && (
        <VStack w="100%" padding="0 12px 12px" gap="8px">
          <VStack w="100%" gap="4px">
            <HTextLabelBox
              isLoading={vaultsFarmingStakeLoading && !vaultsFarmingStaked?.stakedBalanceDisplay}
              label="Your Staked"
              value={
                <VStack alignItems="flex-end">
                  <Text fontSize="14px" color="text_caption">
                    {vaultsFarmingStaked?.stakedBalanceDisplay} LP
                  </Text>
                  <Text fontSize="12px">{symbolDataDisplayProcessing(stakeVaultFarmingTvl)}</Text>
                </VStack>
              }
              skeletonStyle={{
                subValueH: '20px'
              }}
              valueStyle={{
                color: 'text_caption'
              }}
            />
          </VStack>
          <VStack w="100%">
            <HTextLabelBox
              label="Your Rewards"
              isLoading={vaultsFarmingStakeLoading && !vaultsFarmingAvailableRewards}
              rightValueTip={vaultsFarmingAvailableRewards?.map((item: any) => {
                return (
                  <VStack borderRadius="12px">
                    <RewardItem rewardInfo={item} />
                  </VStack>
                )
              })}
              value={
                <HStack position="relative">
                  <Text color="text_caption">{symbolDataDisplayProcessing(vaultFarmingRewardAmountUSD)}</Text>
                  {vaultsFarmingStaked?.rewardConfigs?.map((item: any) => {
                    return (
                      <SingleCoinImage
                        key={item?.coinDetail?.name + 'Icon'}
                        imageUrl={item?.coinDetail?.logo_url}
                        w="20px"
                        h="20px"
                        coinType={item?.coin_type}
                        showTag={false}
                      />
                    )
                  })}
                </HStack>
              }
              valueStyle={{
                textDecoration: 'none'
              }}
              wrapStyle={{
                mt: '4px'
              }}
            />
          </VStack>
          <Button
            w="100%"
            mt="12px"
            height="32px"
            borderRadius="8px"
            fontSize="12px"
            isDisabled={stakeButtonDisabled}
            onClick={() => {
              setIsOpenPre(false)
              setFarmingModalAction('Stake')
              setIsOpenFarmingModal(true)
            }}
          >
            Stake
          </Button>
          <HStack w="100%" justifyContent="space-between">
            <Button
              w="50%"
              height="32px"
              variant="outline"
              borderRadius="8px"
              fontSize="12px"
              bg="none"
              isDisabled={unStakeButtonDisabled}
              onClick={() => {
                setIsOpenPre(false)
                setFarmingModalAction('Unstake')
                setIsOpenFarmingModal(true)
              }}
            >
              Unstake
            </Button>
            <Button
              w="50%"
              height="32px"
              variant="outline"
              borderRadius="8px"
              fontSize="12px"
              bg="none"
              onClick={farmClaimAction}
              isDisabled={claimButtonDisabled}
            >
              Claim
            </Button>
          </HStack>
        </VStack>
      )}
    </VStack>
  )
}
