import useTokenPrice from '@cetus/hooks/src/useTokenPrice'
import { useAccountStore } from '@cetus/stores'
import { d } from '@cetusprotocol/common-sdk'
import { useEffect, useState } from 'react'

export default function useCalculateVaultFarmingRewardUSD(vaultsFarmingAvailableRewards: any[]) {
  const { getTokenAmountValue } = useTokenPrice()

  const [vaultFarmingRewardAmountUSD, setVaultFarmingRewardAmountUSD] = useState('0')
  const [vaultFarmingRewardLoading, setVaultFarmingRewardLoading] = useState(true)
  const [vaultFarmingRewardAmount, setVaultFarmingRewardAmount] = useState('0')
  const { currentAccount } = useAccountStore()
  useEffect(() => {
    const calculate = async () => {
      if (!currentAccount?.address) {
        setVaultFarmingRewardAmountUSD('--')
        setVaultFarmingRewardLoading(false)
        return
      }
      if (!vaultsFarmingAvailableRewards || vaultsFarmingAvailableRewards.length === 0) {
        setVaultFarmingRewardAmountUSD('0')
        return
      }

      setVaultFarmingRewardLoading(true)
      try {
        let totalUSD = d(0)
        let totalAmount = d(0)
        for (const item of vaultsFarmingAvailableRewards) {
          const amountUSD = getTokenAmountValue(item.rewardCoinType, item.rewardAmountDisplay)
          totalUSD = totalUSD.add(amountUSD)
          totalAmount = totalAmount.add(item.rewardAmountDisplay)
        }
        setVaultFarmingRewardAmountUSD(totalUSD.toString())
        setVaultFarmingRewardAmount(totalAmount.toString())
      } catch (err) {
        console.error('Error calculating vault farming reward USD:', err)
        setVaultFarmingRewardAmountUSD('0')
      } finally {
        setVaultFarmingRewardLoading(false)
      }
    }

    calculate()
  }, [vaultsFarmingAvailableRewards, getTokenAmountValue, currentAccount?.address])

  return { vaultFarmingRewardAmountUSD, vaultFarmingRewardLoading, setVaultFarmingRewardLoading, vaultFarmingRewardAmount }
}
