import useVaultsFarmingStore from '@/store/vaults-farming'
import useVaultsPositionStore from '@/store/vaults-v2/useVaultsPosition'
import SelectTab, { Tab } from '@cetus/design/src/components/common/SelectTab'
import { BackButton } from '@cetus/ui-kit'
import { Modal, ModalBody, ModalCloseButton, ModalContent, ModalHeader, ModalOverlay, VStack } from '@chakra-ui/react'
import { useMemo, useState } from 'react'
import { FarmingStake } from './FarmingStake'
import { FarmingUnstake } from './FarmingUnstake'
type FarmingModalProps = {
  isOpen: boolean
  setIsOpen: (isOpen: boolean) => void
  setIsOpenPre: (isOpen: boolean) => void
  onClose: () => void
  farmingModalAction: string
  vaultsId: string
  vaultsFarmingId: string
  isDetail: boolean
}

export function FarmingModal({
  isOpen,
  onClose,
  setIsOpen,
  setIsOpenPre,
  farmingModalAction,
  vaultsFarmingId,
  vaultsId,
  isDetail
}: FarmingModalProps) {
  const { vaultsFarmingObj } = useVaultsFarmingStore()
  console.log('🚀🚀🚀 ~ index.tsx:20 ~ FarmingModal ~ vaultsFarmingObj:', vaultsFarmingObj)
  const [currentActionTab, setCurrentActionTab] = useState(farmingModalAction || 'Stake')
  const { currentVaultPosition } = useVaultsPositionStore()
  const currentVaultsFarming = useMemo(() => {
    console.log('🚀🚀🚀 ~ index.tsx:25 ~ currentVaultsFarming ~ vaultsFarmingObj:', vaultsFarmingObj)
    console.log('🚀🚀🚀 ~ index.tsx:26 ~ currentVaultsFarming ~ vaultsId:', vaultsId)
    return vaultsFarmingObj[vaultsId]
  }, [vaultsFarmingObj, vaultsId])
  console.log('🚀🚀🚀 ~ index.tsx:27 ~ currentVaultsFarming ~ currentVaultsFarming:', currentVaultsFarming)

  const tabList: Tab[] = [
    {
      label: 'Stake',
      value: 'Stake'
    },
    {
      label: 'Unstake',
      value: 'Unstake'
    }
  ]

  console.log('🚀🚀🚀 ~ index.tsx:52 ~ isDetail:', isDetail)
  return (
    <Modal
      isCentered
      isOpen={isOpen}
      onClose={() => {
        setIsOpen(false)
      }}
    >
      <ModalOverlay />
      <ModalContent width={{ base: '100%', lg: '420px' }}>
        <ModalHeader>
          {isDetail && 'Haedal Farms'}
          {!isDetail && (
            <BackButton
              w="100%"
              border="none"
              bg="none"
              justifyContent="start"
              text={'Haedal Farms'}
              ml="-6px"
              valueStyle={{
                color: 'text_caption',
                fontSize: '16px'
              }}
              customTextStyle={{
                color: 'text_caption'
              }}
              onClick={() => {
                setIsOpen(false)
                setIsOpenPre(true)
              }}
            />
          )}
        </ModalHeader>
        <ModalCloseButton />
        <ModalBody p="0 16px 8px">
          <SelectTab
            type="borderTab"
            wrapStyle={{
              w: '100%',
              h: '38px',
              border: 'none',
              bg: 'none'
            }}
            itemStyle={{
              fontSize: '16px',
              mr: '28px',
              fontWeight: '500'
            }}
            tabList={tabList}
            currentTab={currentActionTab}
            handleChangeTab={(item: Tab) => {
              setCurrentActionTab(item.value)
            }}
          />
          <VStack gap="16px" mt="16px" pb="8px">
            {currentActionTab === 'Stake' && <FarmingStake currentVaultPosition={currentVaultPosition} currentVaultsFarming={currentVaultsFarming} />}
            {currentActionTab === 'Unstake' && (
              <FarmingUnstake currentVaultPosition={currentVaultPosition} currentVaultsFarming={currentVaultsFarming} />
            )}
          </VStack>
        </ModalBody>
      </ModalContent>
    </Modal>
  )
}
